        for (_iterator.s(); !(_step = _iterator.n()).done;) {
          var view = _step.value;
          this.updateView(view);
          if (isFirstView) {
            this.handleFirstView(frame, time);
            isFirstView = false;
          }
          this.threeRenderer.render(scene, scene.getCamera());
        }
      } catch (err) {
        _iterator.e(err);
      } finally {
        _iterator.f();
      }
    }
    /**
     * Calculate optimal scale and position for world-space AR presentation
     * Similar to the SVXR:FrameModel approach for consistent model presentation
     *
     * This method implements automatic model framing for world-space AR sessions:
     * 1. Calculates optimal viewing distance based on model size and minimum
     * distance
     * 2. Positions model at a drop angle below camera center for natural viewing
     * 3. Automatically scales model to fit within viewport constraints
     * 4. Ensures consistent presentation across different model sizes
     *
     * Note: This automatic placement only happens on the first session start.
     * After initial placement, users have full control over model position,
     * rotation, and scale.
     */
  }, {
    key: "calculateWorldSpaceOptimalPlacement",
    value: function calculateWorldSpaceOptimalPlacement(scene, camera) {
      // Get model bounding box half extents
      var boundingBox = scene.boundingBox;
      var halfExtent = {
        x: (boundingBox.max.x - boundingBox.min.x) / 2,
        y: (boundingBox.max.y - boundingBox.min.y) / 2,
        z: (boundingBox.max.z - boundingBox.min.z) / 2
      };
      // Compute view distance (with extra padding for model-viewer)
      var placementBoxPadding = PLACEMENT_BOX_EXTRA_PADDING;
      var viewDistance = Math.max(MIN_WORLD_SPACE_DISTANCE + placementBoxPadding, 2 * Math.max(halfExtent.x, halfExtent.z) + placementBoxPadding);
      // Compute ideal view position (drop angle below camera center)
      var dropAngleRad = VIEW_DROP_DEGREES * Math.PI / 180;
      var idealViewPosition = new Vector3(0, -viewDistance * Math.sin(dropAngleRad), -viewDistance * Math.cos(dropAngleRad));
      // Transform ideal view position to world space
      var worldFromCamera = camera.matrixWorld;
      var idealWorldPosition = idealViewPosition.clone().applyMatrix4(worldFromCamera);
      // Compute turntable and vertical radii
      var turntableRadius = Math.max(halfExtent.x, halfExtent.z) + placementBoxPadding;
      var verticalRadius = halfExtent.y;
      var turntableRadiusLimit = viewDistance * VIEW_RATIO;
      var verticalRadiusLimit = viewDistance * VIEW_RATIO;
      // Compute optimal scale
      var verticalScale = verticalRadiusLimit / Math.max(verticalRadius, MIN_MODEL_SIZE);
      var turntableScale = turntableRadiusLimit / Math.max(turntableRadius, MIN_MODEL_SIZE);
      var optimalScale = Math.min(verticalScale, turntableScale);
      // Offset so the model's base sits at the ideal world position
      // (subtract scaled half height in Y)
      var finalPosition = idealWorldPosition.clone().sub(new Vector3(0, optimalScale * halfExtent.y, 0));
      return {
        position: finalPosition,
        scale: optimalScale
      };
    }
    /**
     * Calculate min/max scale for world-space AR, SVXR-style
     */
  }, {
    key: "calculateWorldSpaceScaleLimits",
    value: function calculateWorldSpaceScaleLimits(scene) {
      var size = scene.size;
      var largestDimension = Math.max(size.x, size.y, size.z);
      var smallestDimension = Math.max(Math.min(size.x, size.y, size.z), MODEL_SIZE_EPSILON);
      var scaleMin = MIN_MODEL_SIZE / Math.max(largestDimension, MODEL_SIZE_EPSILON);
      var scaleMax = MAX_MODEL_SIZE / Math.max(smallestDimension, MODEL_SIZE_EPSILON);
      // Clamp to initial scale if needed
      this.minScale = Math.min(scaleMin, scaleMax, this.goalScale);
      this.maxScale = Math.max(scaleMin, scaleMax, this.goalScale);
    }
  }]);
}(EventDispatcher);

